<?php
require_once __DIR__.'/commerce.php';
function product_save(int $id,array $b): array {admin();$p=one('SELECT * FROM products WHERE id=?',[$id]);if(!$p)fail(404,'product','Produit introuvable.');$price=$b['price_tnd']??null;if(!is_numeric($price)||(float)$price<=0||(float)$price>10000)fail(422,'price','Prix invalide.');q('UPDATE products SET name_fr=?,name_ar=?,price_tnd=?,active=?,commercial_approved=?,price_version=price_version+1 WHERE id=?',[text_field($b,'name_fr',150,true),text_field($b,'name_ar',150,true),$price,checked($b['active']??0),checked($b['commercial_approved']??0),$id]);audit('product.updated','product',$id,['previous_price'=>$p['price_tnd'],'new_price'=>$price]);return ['product'=>one('SELECT * FROM products WHERE id=?',[$id])];}
function promo_save(array $b): array {admin();$code=strtoupper(text_field($b,'code',50,true));if(!preg_match('/^[A-Z0-9_-]{3,50}$/',$code))fail(422,'code','Code invalide.');$type=enum_field($b,'discount_type',['percent','fixed']);$value=$b['discount_value']??null;if(!is_numeric($value)||(float)$value<=0||($type==='percent'&&((float)$value>100||floor((float)$value)!=(float)$value)))fail(422,'discount','Remise invalide.');$quota=max(1,(int)($b['usage_limit']??1));$personal=max(1,(int)($b['per_user_limit']??1));$pid=(int)($b['applicable_product_id']??0);if($pid&&!one('SELECT id FROM products WHERE id=?',[$pid]))fail(422,'product','Produit invalide.');foreach(['starts_at','expires_at'] as $date)if(!empty($b[$date])&&!strtotime($b[$date]))fail(422,'date','Date invalide.');q('INSERT INTO promo_codes(code,discount_type,discount_value,min_order_tnd,applicable_product_id,usage_limit,per_user_limit,active,starts_at,expires_at,stackable) VALUES(?,?,?,?,?,?,?,?,?,?,?)',[$code,$type,$value,max(0,(float)($b['min_order_tnd']??0)),$pid?:null,$quota,$personal,checked($b['active']??0),empty($b['starts_at'])?null:gmdate('Y-m-d H:i:s',strtotime($b['starts_at'])),empty($b['expires_at'])?null:gmdate('Y-m-d H:i:s',strtotime($b['expires_at'])),checked($b['stackable']??0)]);$id=(int)db()->lastInsertId();audit('promo.created','promo',$id);return ['promo_id'=>$id];}
function content_save(array $b,array $u): array {$slug=text_field($b,'slug',120,true);if(!preg_match('/^[a-z0-9][a-z0-9\/-]*$/',$slug))fail(422,'slug','Identifiant de contenu invalide.');$status=enum_field($b,'status',['draft','published'],'draft');$fr=text_field($b,'body_fr',30000,$status==='published')??'';$ar=text_field($b,'body_ar',30000,$status==='published')??'';q('INSERT INTO content_versions(slug,title_fr,title_ar,body_fr,body_ar,status,author_id,published_at) VALUES(?,?,?,?,?,?,?,IF(?="published",UTC_TIMESTAMP(),NULL))',[$slug,text_field($b,'title_fr',200,true),text_field($b,'title_ar',200,true),$fr,$ar,$status,$u['id'],$status]);$id=(int)db()->lastInsertId();audit('content.'.$status,'content',$id,['slug'=>$slug]);return ['content_id'=>$id];}
function crm_contact_save(array $b,array $u): array {$name=text_field($b,'name',150,true);$email=text_field($b,'email',190);if($email&&!filter_var($email,FILTER_VALIDATE_EMAIL))fail(422,'email','Email invalide.');$uid=(int)($b['user_id']??0);if($uid&&!one('SELECT id FROM users WHERE id=? AND role="customer"',[$uid]))fail(422,'customer','Compte client introuvable.');$cid=(int)($b['companion_id']??0);if($cid)companion($cid);q('INSERT INTO crm_contacts(user_id,name,email,phone,kind,companion_id) VALUES(?,?,?,?,?,?)',[$uid?:null,$name,$email,text_field($b,'phone',40),$uid?'customer':'prospect',$cid?:null]);$id=(int)db()->lastInsertId();audit('crm.contact.created','crm_contact',$id);return ['contact_id'=>$id];}
function crm_activity_save(int $id,array $b,array $u): array {if(!one('SELECT id FROM crm_contacts WHERE id=?',[$id]))fail(404,'contact','Contact introuvable.');$type=enum_field($b,'type',['note','interaction','followup'],'note');$assigned=(int)($b['assigned_to']??$u['id']);if(!one('SELECT id FROM users WHERE id=? AND role="admin" AND status="active"',[$assigned]))fail(422,'assignee','Responsable invalide.');$due=text_field($b,'due_at',25);if($type==='followup'&&(!$due||!strtotime($due)))fail(422,'due','Échéance requise.');q('INSERT INTO crm_activity(contact_id,actor_id,type,channel,body,due_at,assigned_to) VALUES(?,?,?,?,?,?,?)',[$id,$u['id'],$type,enum_field($b,'channel',['call','whatsapp','email','message','in_person','other'],'other'),text_field($b,'body',6000,true),$due?gmdate('Y-m-d H:i:s',strtotime($due)):null,$assigned]);$aid=(int)db()->lastInsertId();audit('crm.'.$type.'.created','crm_activity',$aid);return ['activity_id'=>$aid,'message'=>tr('Échange enregistré. Aucun message externe envoyé.','تم تسجيل التفاعل. لم تُرسل رسالة خارجية.')];}
